import{_ as t,o as s,c as i,a2 as a}from"./chunks/framework.C8822HRV.js";const g=JSON.parse('{"title":"Keep AI coding decisions in git","description":"AI coding agents write fast, but intent dies in chat. Local Spec-Driven Development (sdd) keeps plans, stages, and handoffs in git so Copilot, Claude Code, Grok, and Ollama share the same trail.","frontmatter":{"title":"Keep AI coding decisions in git","description":"AI coding agents write fast, but intent dies in chat. Local Spec-Driven Development (sdd) keeps plans, stages, and handoffs in git so Copilot, Claude Code, Grok, and Ollama share the same trail.","head":[["meta",{"property":"og:title","content":"Keep AI coding decisions in git · sdd"}],["meta",{"property":"og:description","content":"AI coding agents write fast, but intent dies in chat. Local Spec-Driven Development (sdd) keeps plans, stages, and handoffs in git so Copilot, Claude Code, Grok, and Ollama share the same trail."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/concepts/keep-ai-coding-in-git/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"Keep AI coding decisions in git · sdd"}],["meta",{"name":"twitter:description","content":"AI coding agents write fast, but intent dies in chat. Local Spec-Driven Development (sdd) keeps plans, stages, and handoffs in git so Copilot, Claude Code, Grok, and Ollama share the same trail."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/concepts/keep-ai-coding-in-git/"}]]},"headers":[],"relativePath":"concepts/keep-ai-coding-in-git.md","filePath":"concepts/keep-ai-coding-in-git.md","lastUpdated":1785895617000}'),n={name:"concepts/keep-ai-coding-in-git.md"};function o(r,e,d,l,h,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="keep-ai-coding-decisions-in-git" tabindex="-1">Keep AI coding decisions in git <a class="header-anchor" href="#keep-ai-coding-decisions-in-git" aria-label="Permalink to &quot;Keep AI coding decisions in git&quot;">​</a></h1><p><strong>AI coding agents</strong> (GitHub Copilot, Claude Code, Grok, Ollama, and similar tools) can change a lot of code before lunch. By the next day, the hard parts—why that edge case was “fine,” what was out of scope, what “done” meant—are often <strong>only in a chat thread</strong>.</p><p>That is not a model problem. It is a <strong>process and storage</strong> problem.</p><p><strong>Local Spec-Driven Development</strong> means: short specs and progress live <strong>in your repository</strong>, next to the code, so humans and agents read the same files. <strong>sdd</strong> is a CLI that runs that process without a cloud process product or a required IDE extension.</p><hr><h2 id="the-failure-mode-of-chat-only-coding" tabindex="-1">The failure mode of chat-only coding <a class="header-anchor" href="#the-failure-mode-of-chat-only-coding" aria-label="Permalink to &quot;The failure mode of chat-only coding&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What happens</th><th>Why it hurts</th></tr></thead><tbody><tr><td>Decisions stay in the agent chat</td><td>New chats (or new teammates) start from zero</td></tr><tr><td>PRs show diffs, not intent</td><td>Reviewers re-discover the “why” from code alone</td></tr><tr><td>Context windows fill with source</td><td>Plans get compressed away; constraints are forgotten</td></tr><tr><td>Process is “vibe” until it isn’t</td><td>Hotfixes and platform work need different depth</td></tr></tbody></table><p>If this feels familiar, you do not need a heavier enterprise ALM suite for every three-line fix. You need a <strong>light spine in git</strong>.</p><hr><h2 id="what-local-spec-driven-development-looks-like" tabindex="-1">What local Spec-Driven Development looks like <a class="header-anchor" href="#what-local-spec-driven-development-looks-like" aria-label="Permalink to &quot;What local Spec-Driven Development looks like&quot;">​</a></h2><ol><li>Start a piece of work (<code>sdd new &quot;…&quot;</code>, or <code>sdd greenfield</code> for a new product).</li><li>Fill a <strong>short markdown</strong> file (intent, design, tasks—not a novel).</li><li>Advance with <code>sdd next</code> when the step is real.</li><li>Implement, verify, then <code>sdd complete</code>.</li></ol><p>Notes for <em>this</em> PR live under <code>changes/</code>. Product truths that should last live under <code>memory/</code> (constitution, backlog after greenfield, thin architecture).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Chat / agent window          Your repo (source of truth)</span></span>
<span class="line"><span>        │                              │</span></span>
<span class="line"><span>        │     sdd handoff + packs      │</span></span>
<span class="line"><span>        └─────────────────────────────►│  changes/ · memory/ · .sdd/</span></span></code></pre></div><p>Agents get a <strong>handoff</strong> and host rules; you still own the process with the CLI.</p><hr><h2 id="how-sdd-fits-and-what-it-is-not" tabindex="-1">How sdd fits (and what it is not) <a class="header-anchor" href="#how-sdd-fits-and-what-it-is-not" aria-label="Permalink to &quot;How sdd fits (and what it is not)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>sdd is</th><th>sdd is not</th></tr></thead><tbody><tr><td>A <strong>Spec-Driven Development CLI</strong> (<code>npm i -g @structured-vibe-coding/cli</code>)</td><td>A cloud ticket system</td></tr><tr><td>Process coach for <strong>you + your AI coding agent</strong></td><td>A replacement for your framework or IDE</td></tr><tr><td>Markdown in git, progressive workflows (hotfix → enterprise)</td><td>One rigid ceremony for every change</td></tr><tr><td>Optional <strong>MCP sources</strong> sdd <em>calls</em> (design system, AST, APIs)</td><td>An inbound “drive sdd next from Cursor tools” server (by design)</td></tr></tbody></table><hr><h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><ul><li>Solo and small teams using agents daily</li><li>Teams that want <strong>decisions reviewable in PRs</strong></li><li>Greenfield MVPs that need a <strong>vision → backlog → F-001</strong> path</li><li>Groups that sometimes need <strong>gates</strong> without living in them</li></ul><p>Not for: people who want process only in a SaaS UI, or who refuse any markdown next to code.</p><hr><h2 id="try-it-in-about-10-minutes" tabindex="-1">Try it in about 10 minutes <a class="header-anchor" href="#try-it-in-about-10-minutes" aria-label="Permalink to &quot;Try it in about 10 minutes&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @structured-vibe-coding/cli</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --here</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copilot</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # or grok | claude | ollama</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Fix empty list crash&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hotfix</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-agent</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># write a few real sentences in the intent file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-agent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> complete</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-agent</span></span></code></pre></div><p>Step-by-step: <strong><a href="./../tutorials/first-change">Start in 10 minutes</a></strong>.<br> Product concept: <strong><a href="./what-is-sdd">What is sdd?</a></strong>.<br> Why this exists: <strong><a href="./why-sdd">Why sdd exists</a></strong>.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./change-packs">Change packs &amp; memory</a> — what to keep forever vs per PR</li><li><a href="./../guides/agents">Set up your AI</a> — Copilot, Claude Code, Grok, Ollama</li><li><a href="./../guides/greenfield">Greenfield</a> — new product from one sentence</li><li><a href="./../reference/cli">CLI reference</a> — commands</li></ul>`,28)])])}const k=t(n,[["render",o]]);export{g as __pageData,k as default};
